func (this *StyledText) ModifyContent(eventLike EventLike, updateCaret bool) {
	var event *Event
	if eventLike != nil {
		event = eventLike.AsEvent()
	}
	_ = event
	event.Doit = true
	this.NotifyListeners(Verify, event)
	if event.Doit {
		var styledTextEvent *StyledTextEvent = nil
		var replacedLength int32 = event.End - event.Start
		if this.IsListening(STExtendedModify) {
			styledTextEvent = newStyledTextEvent(this.content)
			styledTextEvent.Start = event.Start
			styledTextEvent.End = event.Start + jrt.StringLength(event.Text)
			styledTextEvent.Text = this.content.GetTextRange(event.Start, replacedLength)
		}
		if updateCaret {
			if jrt.StringLength(event.Text) == 0 {
				var lineIndex int32 = this.content.GetLineAtOffset(event.Start)
				var lineOffset int32 = this.content.GetOffsetAtLine(lineIndex)
				var layout *TextLayout = this.renderer.GetTextLayout(lineIndex)
				var levelStart int32 = layout.GetLevel(event.Start - lineOffset)
				var lineIndexEnd int32 = this.content.GetLineAtOffset(event.End)
				if lineIndex != lineIndexEnd {
					this.renderer.DisposeTextLayout(layout)
					lineOffset = this.content.GetOffsetAtLine(lineIndexEnd)
					layout = this.renderer.GetTextLayout(lineIndexEnd)
				}
				var levelEnd int32 = layout.GetLevel(event.End - lineOffset)
				this.renderer.DisposeTextLayout(layout)
				if levelStart != levelEnd {
					this.caretAlignment = StyledTextPREVIOUS_OFFSET_TRAILING
				} else {
					this.caretAlignment = StyledTextOFFSET_LEADING
				}
			}
		}
		this.content.ReplaceTextRange(event.Start, replacedLength, event.Text)
		if updateCaret && !(this.blockSelection && this.blockXLocation != -1) {
			this.SetSelectionRegionsSendEventDoBlock(jrt.ToSlice[int32](jrt.ArraysAsList(this.selection).Map(func(sel *Point) *Point {
				if sel.Y < event.Start || sel.X > event.End {
					return sel
				} else {
					return NewPoint(event.Start+jrt.StringLength(event.Text), event.Start+jrt.StringLength(event.Text))
				}
			}).FlatMapToInt(func(p *Point) *jrt.List {
				return jrt.IntStreamOf(p.X, p.Y-p.X)
			})), true, false)
			this.ShowCaret()
		}
		this.NotifyListeners(Modify, event)
		if this.IsListening(STExtendedModify) {
			this.NotifyListeners(STExtendedModify, upcastStyledTextEventToEvent(styledTextEvent))
		}
	}
}

