func (this *StyledText) Paste() {
	this.CheckWidget()
	var text string = jrt.Cast[string](this.GetClipboardContent(DNDCLIPBOARD))
	if text != "" && jrt.StringLength(text) > 0 {
		if this.blockSelection {
			var fillWithSpaces bool = this.IsFixedLineHeight() && this.renderer.fixedPitch
			var offset int32 = this.InsertBlockSelectionText(text, fillWithSpaces)
			this.SetCaretOffsets([]int32{offset}, DEFAULT)
			this.ClearBlockSelection(true, true)
			this.SetCaretLocations()
			return
		} else {
			if int32(len(this.GetSelectionRanges()))/2 > 1 {
				this.InsertMultiSelectionText(text)
				this.SetCaretLocations()
				return
			}
		}
		var event *Event = NewEvent()
		event.Start = this.selection[0].X
		event.End = this.selection[0].Y
		var delimitedText string = this.GetModelDelimitedText(text)
		if this.textLimit > 0 {
			var uneditedTextLength int32 = this.GetCharCount() - (this.selection[0].Y - this.selection[0].X)
			if (uneditedTextLength + jrt.StringLength(delimitedText)) > this.textLimit {
				var endIndex int32 = this.textLimit - uneditedTextLength
				delimitedText = jrt.Substring(delimitedText, 0, int32(math.Max(float64(endIndex), float64(0))))
			}
		}
		event.Text = delimitedText
		this.SendKeyEvent(event)
	}
}

func (this *StyledText) InsertMultiSelectionText(text string) {
	var blocks []string = jrt.Split(text, StyledTextPlatformLineDelimiter)
	var ranges []int32 = this.GetSelectionRanges()
	for i := int32(int32(len(ranges))/2 - 1); i >= 0; i-- {
		var offset int32 = ranges[2*i]
		var length int32 = ranges[2*i+1]
		var toPaste string
		if int32(len(blocks)) > i {
			toPaste = blocks[i]
		} else {
			toPaste = blocks[int32(len(blocks))-1]
		}
		var event *Event = NewEvent()
		event.Start = offset
		event.End = offset + length
		event.Text = toPaste
		this.SendKeyEvent(event)
	}
}

