func (this *StyledText) setEnabled_(enabled bool) {
	this.Canvas.setEnabled_(enabled)
	var display *Display = this.GetDisplay()
	this.enabled = enabled
	this.insideSetEnableCall = true
	{
		defer func() {
			this.insideSetEnableCall = false
		}()
		if enabled && this.editable {
			if !this.customBackground {
				this.impl.setBackgroundWithColor_(display.impl.getSystemColor_(COLOR_LIST_BACKGROUND))
			}
			if !this.customForeground {
				this.impl.setForeground_(display.impl.getSystemColor_(COLOR_LIST_FOREGROUND))
			}
		} else {
			if !enabled {
				if !this.customBackground {
					this.impl.setBackgroundWithColor_(display.impl.getSystemColor_(COLOR_TEXT_DISABLED_BACKGROUND))
				}
				if !this.customForeground {
					this.impl.setForeground_(display.impl.getSystemColor_(COLOR_WIDGET_DISABLED_FOREGROUND))
				}
			} else {
				if !this.editable {
					if !this.customBackground {
						this.impl.setBackgroundWithColor_(display.impl.getSystemColor_(COLOR_TEXT_DISABLED_BACKGROUND))
					}
					if !this.customForeground {
						this.impl.setForeground_(display.impl.getSystemColor_(COLOR_LIST_FOREGROUND))
					}
				}
			}
		}
	}
}

func (this *StyledText) setFocus_() bool {
	var focusGained bool = this.Canvas.setFocus_()
	if focusGained && this.HasMultipleCarets() {
		this.SetCaretLocations()
	}
	return focusGained
}

