func (this *StyledText) setFont_(font *Font) {
	this.CheckWidget()
	var oldLineHeight int32 = this.renderer.GetLineHeight()
	this.Canvas.setFont_(font)
	this.renderer.SetFont(this.GetFont(), this.tabLength)
	if this.IsFixedLineHeight() {
		var lineHeight int32 = this.renderer.GetLineHeight()
		if lineHeight != oldLineHeight {
			var vscroll int32 = (this.GetVerticalScrollOffset() * lineHeight / oldLineHeight) - this.GetVerticalScrollOffset()
			this.ScrollVertical(vscroll, true)
		}
	}
	this.ResetCacheFirstLineCount(0, this.content.GetLineCount())
	this.ClaimBottomFreeSpace()
	this.CalculateScrollBars()
	if this.IsBidiCaret() {
		this.CreateCaretBitmaps()
	}
	this.caretDirection = NULL
	this.SetCaretLocations()
	this.Canvas.redraw_()
}

func (this *StyledText) setForeground_(color *Color) {
	this.CheckWidget()
	var foregroundDisabled bool = false
	if !this.enabled && color == (nil) {
		if this.foreground != (nil) {
			var disabledFg *Color = this.GetDisplay().impl.getSystemColor_(COLOR_WIDGET_DISABLED_FOREGROUND)
			if this.foreground.Equals(disabledFg) {
				return
			} else {
				color = NewColorRgba(disabledFg.GetRGBA())
				foregroundDisabled = true
			}
		}
	}
	this.customForeground = color != (nil) && !this.insideSetEnableCall && !foregroundDisabled
	this.foreground = color
	this.Canvas.setForeground_(color)
	if this.content != (nil) {
		this.ResetCacheFirstLineCount(0, this.content.GetLineCount())
		this.SetCaretLocations()
	}
	this.Canvas.redraw_()
}

func (this *StyledText) SetHorizontalIndex(offset int32) {
	this.CheckWidget()
	if this.GetCharCount() == 0 {
		return
	}
	if offset < 0 {
		offset = 0
	}
	offset *= this.GetHorizontalIncrement()
	if this.clientAreaWidth > 0 {
		var width int32 = this.renderer.GetWidth()
		if offset > width-this.clientAreaWidth {
			offset = int32(math.Max(float64(0), float64(width-this.clientAreaWidth)))
		}
	}
	this.ScrollHorizontal(offset-this.horizontalScrollOffset, true)
}

