func (this *StyledText) SetKeyBinding(key int32, action int32) {
	this.CheckWidget()
	var modifierValue int32 = key & MODIFIER_MASK
	var keyInt int32 = key & KEY_MASK
	var keyChar uint16 = uint16(keyInt)
	if utf8.ValidRune(rune(keyInt)) && unicode.IsLetter(rune(keyChar)) {
		var ch uint16 = uint16(unicode.ToUpper(rune(keyChar)))
		var newKey int32 = int32(ch) | modifierValue
		if action == NULL {
			this.keyActionMap.Remove(int32(newKey))
		} else {
			this.keyActionMap.Put(int32(newKey), int32(action))
		}
		ch = uint16(unicode.ToLower(rune(keyChar)))
		newKey = int32(ch) | modifierValue
		if action == NULL {
			this.keyActionMap.Remove(int32(newKey))
		} else {
			this.keyActionMap.Put(int32(newKey), int32(action))
		}
	} else {
		if action == NULL {
			this.keyActionMap.Remove(int32(key))
		} else {
			this.keyActionMap.Put(int32(key), int32(action))
		}
	}
}

