func (this *StyledText) SetLineAlignment(startLine int32, lineCount int32, alignment int32) {
	this.CheckWidget()
	if this.IsListening(STLineGetStyle) {
		return
	}
	if startLine < 0 || startLine+lineCount > this.content.GetLineCount() {
		Error(ERROR_INVALID_ARGUMENT)
	}
	this.renderer.SetLineAlignment(startLine, lineCount, alignment)
	this.ResetCacheFirstLineCount(startLine, lineCount)
	this.RedrawLines(startLine, lineCount, false)
	if jrt.ArraysAsList(this.caretOffsets).Map(this.content.GetLineAtOffset).AnyMatch(func(caretLine int32) bool {
		return startLine <= caretLine && caretLine < startLine+lineCount
	}) {
		this.SetCaretLocations()
	}
	this.SetAlignment()
}

