func (this *StyledText) SetLineSpacingProvider(lineSpacingProvider StyledTextLineSpacingProvider) {
	this.CheckWidget()
	var wasFixedLineHeight bool = this.IsFixedLineHeight()
	if this.renderer.GetLineSpacingProvider() == (nil) && lineSpacingProvider == (nil) || (this.renderer.GetLineSpacingProvider() != (nil) && (this.renderer.GetLineSpacingProvider() == lineSpacingProvider)) {
		return
	}
	this.renderer.SetLineSpacingProvider(lineSpacingProvider)
	if lineSpacingProvider == (nil) {
		if !wasFixedLineHeight {
			this.ResetCacheFirstLineCount(0, this.content.GetLineCount())
		}
	} else {
		if wasFixedLineHeight {
			var firstLine int32 = -1
			for i := int32(0); i < this.content.GetLineCount(); i++ {
				var lineSpacing any = lineSpacingProvider.GetLineSpacing(i)
				if !jrt.IsNil(lineSpacing) && jrt.Cast[int32](lineSpacing) > 0 {
					this.renderer.ResetStartLineLineCount(i, 1)
					if firstLine == -1 {
						firstLine = i
					}
				}
			}
			if firstLine != -1 {
				this.ResetCacheFirstLineCount(firstLine, 0)
			}
		}
	}
	this.SetCaretLocations()
	this.Canvas.redraw_()
}

func (this *StyledText) SetLineTabStops(startLine int32, lineCount int32, tabStops []int32) {
	this.CheckWidget()
	if this.IsListening(STLineGetStyle) {
		return
	}
	if startLine < 0 || startLine+lineCount > this.content.GetLineCount() {
		Error(ERROR_INVALID_ARGUMENT)
	}
	if tabStops != (nil) {
		var pos int32 = 0
		var newTabs []int32 = make([]int32, int32(len(tabStops)))
		for i := int32(0); i < int32(len(tabStops)); i++ {
			if tabStops[i] < pos {
				Error(ERROR_INVALID_ARGUMENT)
			}
			pos = tabStops[i]
			newTabs[i] = pos
		}
		this.renderer.SetLineTabStops(startLine, lineCount, newTabs)
	} else {
		this.renderer.SetLineTabStops(startLine, lineCount, nil)
	}
	this.ResetCacheFirstLineCount(startLine, lineCount)
	this.RedrawLines(startLine, lineCount, false)
	if jrt.ArraysAsList(this.caretOffsets).Map(this.content.GetLineAtOffset).AnyMatch(func(caretLine int32) bool {
		return startLine <= caretLine && caretLine < startLine+lineCount
	}) {
		this.SetCaretLocations()
	}
}

