func (this *StyledText) SetScrollBars(vertical bool) {
	this.ignoreResize++
	if !this.IsFixedLineHeight() || !this.alwaysShowScroll {
		vertical = true
	}
	var verticalBar *ScrollBar
	if vertical {
		verticalBar = this.GetVerticalBar()
	} else {
		verticalBar = nil
	}
	var horizontalBar *ScrollBar = this.GetHorizontalBar()
	var oldHeight int32 = this.clientAreaHeight
	var oldWidth int32 = this.clientAreaWidth
	if !this.alwaysShowScroll {
		if verticalBar != (nil) {
			verticalBar.SetVisible(false)
		}
		if horizontalBar != (nil) {
			horizontalBar.SetVisible(false)
		}
	}
	if verticalBar != (nil) {
		this.SetScrollBar(verticalBar, this.clientAreaHeight, this.renderer.GetHeight(), this.topMargin+this.bottomMargin)
	}
	if horizontalBar != (nil) && !this.wordWrap {
		this.SetScrollBar(horizontalBar, this.clientAreaWidth, this.renderer.GetWidth(), this.leftMargin+this.rightMargin)
		if !this.alwaysShowScroll && horizontalBar.GetVisible() && verticalBar != (nil) {
			this.SetScrollBar(verticalBar, this.clientAreaHeight, this.renderer.GetHeight(), this.topMargin+this.bottomMargin)
			if verticalBar.GetVisible() {
				this.SetScrollBar(horizontalBar, this.clientAreaWidth, this.renderer.GetWidth(), this.leftMargin+this.rightMargin)
			}
		}
	}
	if !this.alwaysShowScroll {
		this.RedrawMargins(oldHeight, oldWidth)
	}
	this.ignoreResize--
}

