func (this *StyledText) SetSelectionRegionsSendEventDoBlock(regions []int32, sendEvent bool, doBlock bool) {
	if int32(len(regions)) == 2 && int32(len(this.selection)) == 1 {
		var start int32 = regions[0]
		var length int32 = regions[1]
		var end int32 = start + length
		if start > end {
			var temp int32 = end
			end = start
			start = temp
		}
		var selectionAnchor int32 = this.selectionAnchors[0]
		if this.selection[0].X != start || this.selection[0].Y != end || (length > 0 && selectionAnchor != this.selection[0].X) || (length < 0 && selectionAnchor != this.selection[0].Y) {
			if this.blockSelection && doBlock {
				if length < 0 {
					this.SetBlockSelectionOffsetAnchorOffsetOffsetSendEvent(end, start, sendEvent)
				} else {
					this.SetBlockSelectionOffsetAnchorOffsetOffsetSendEvent(start, end, sendEvent)
				}
			} else {
				var oldStart int32 = this.selection[0].X
				var oldLength int32 = this.selection[0].Y - this.selection[0].X
				var charCount int32 = this.content.GetCharCount()
				var redrawX int32 = int32(math.Min(float64(this.selection[0].X), float64(charCount)))
				var redrawY int32 = int32(math.Min(float64(this.selection[0].Y), float64(charCount)))
				if length < 0 {
					this.selection[0].Y = end
					selectionAnchor = this.selection[0].Y
					this.selectionAnchors[0] = selectionAnchor
					this.selection[0].X = start
					this.SetCaretOffsets([]int32{start}, StyledTextPREVIOUS_OFFSET_TRAILING)
				} else {
					this.selection[0].X = start
					selectionAnchor = this.selection[0].X
					this.selectionAnchors[0] = selectionAnchor
					this.selection[0].Y = end
					this.SetCaretOffsets([]int32{end}, StyledTextPREVIOUS_OFFSET_TRAILING)
				}
				redrawX = int32(math.Min(float64(redrawX), float64(this.selection[0].X)))
				redrawY = int32(math.Max(float64(redrawY), float64(this.selection[0].Y)))
				if redrawY-redrawX > 0 {
					this.InternalRedrawRange(redrawX, redrawY-redrawX)
				}
				if sendEvent && (oldLength != end-start || (oldLength != 0 && oldStart != start)) {
					this.SendSelectionEvent()
				}
				this.SendAccessibleTextCaretMoved()
			}
		}
	} else {
		if !this.blockSelection || !doBlock {
			var caretAtEndOfSelection bool = regions[1] > 0
			var charCount int32 = this.content.GetCharCount()
			var newRanges []*Point = make([]*Point, int32(len(regions))/2)
			for i := int32(0); i < int32(len(regions)); i += 2 {
				var start int32 = regions[i]
				var length int32 = regions[i+1]
				var end int32 = start + length
				if start > end {
					var temp int32 = end
					end = start
					start = temp
				}
				newRanges[i/2] = NewPoint(start, end)
			}
			jrt.ArraysSortComparator(newRanges, StyledTextSELECTION_COMPARATOR)
			var newRangeIndex int32 = 0
			for _, range_ := range newRanges {
				if newRangeIndex > 0 {
					var previousRange *Point = newRanges[newRangeIndex-1]
					if previousRange.Y >= range_.X {
						previousRange.Y = int32(math.Max(float64(previousRange.Y), float64(range_.Y)))
					} else {
						newRanges[newRangeIndex] = range_
						newRangeIndex++
					}
				} else {
					newRanges[newRangeIndex] = range_
					newRangeIndex++
				}
			}
			var toRedraw []*Point = make([]*Point, newRangeIndex+int32(len(this.selection)))
			copy(toRedraw[0:], newRanges[0:0+newRangeIndex])
			copy(toRedraw[newRangeIndex:], this.selection[0:0+int32(len(this.selection))])
			jrt.ArraysSortComparator(toRedraw, StyledTextSELECTION_COMPARATOR)
			var formerSelection []*Point = this.selection
			this.selection = jrt.CopyOf(newRanges, newRangeIndex)
			var currentToRedraw *Point = nil
			for _, p := range toRedraw {
				if currentToRedraw == (nil) {
					currentToRedraw = NewPoint(p.X, p.Y)
				} else {
					if currentToRedraw.Y >= p.X-1 {
						currentToRedraw = NewPoint(currentToRedraw.X, int32(math.Max(float64(p.Y), float64(currentToRedraw.Y))))
					} else {
						currentToRedraw = NewPoint(int32(math.Max(float64(0), float64(currentToRedraw.X))), int32(math.Min(float64(charCount), float64(currentToRedraw.Y))))
						this.InternalRedrawRange(currentToRedraw.X, currentToRedraw.Y-currentToRedraw.X)
						currentToRedraw = nil
					}
				}
			}
			if currentToRedraw != (nil) {
				currentToRedraw = NewPoint(int32(math.Max(float64(0), float64(currentToRedraw.X))), int32(math.Min(float64(charCount), float64(currentToRedraw.Y))))
				this.InternalRedrawRange(currentToRedraw.X, currentToRedraw.Y-currentToRedraw.X)
			}
			if !caretAtEndOfSelection {
				this.selectionAnchors = jrt.ToSlice[int32](jrt.ArraysAsList(this.selection).MapToInt(func(p *Point) int32 {
					return p.Y
				}))
				this.SetCaretOffsets(jrt.ToSlice[int32](jrt.ArraysAsList(this.selection).MapToInt(func(p *Point) int32 {
					return p.X
				})), StyledTextPREVIOUS_OFFSET_TRAILING)
			} else {
				this.selectionAnchors = jrt.ToSlice[int32](jrt.ArraysAsList(this.selection).MapToInt(func(p *Point) int32 {
					return p.X
				}))
				this.SetCaretOffsets(jrt.ToSlice[int32](jrt.ArraysAsList(this.selection).MapToInt(func(p *Point) int32 {
					return p.Y
				})), StyledTextPREVIOUS_OFFSET_TRAILING)
			}
			this.SetCaretLocations()
			if sendEvent && !slices.Equal(formerSelection, this.selection) {
				this.SendSelectionEvent()
			}
			this.SendAccessibleTextCaretMoved()
		}
	}
}

