func (this *StyledText) SetSelectionRanges(ranges []int32) {
	this.CheckWidget()
	var contentLength int32 = this.GetCharCount()
	if int32(len(ranges))%2 != 0 {
		Error(ERROR_INVALID_ARGUMENT)
	}
	var fixedRanges []int32 = jrt.CopyOf(ranges, int32(len(ranges)))
	for i := int32(0); i < int32(len(ranges)); i += 2 {
		var start int32 = ranges[i]
		start = int32(math.Max(float64(0), float64(int32(math.Min(float64(start), float64(contentLength))))))
		var length int32 = ranges[i+1]
		var end int32 = start + length
		if end < 0 {
			length = -start
		} else {
			if end > contentLength {
				length = contentLength - start
			}
		}
		if this.IsLineDelimiter(start) || this.IsLineDelimiter(start+length) {
			Error(ERROR_INVALID_ARGUMENT)
		}
		fixedRanges[i] = start
		fixedRanges[i+1] = length
	}
	this.SetSelectionRegionsSendEventDoBlock(fixedRanges, false, true)
	this.SetCaretLocations()
}

