func (this *StyledText) SetStyleRangesStartLengthRangesStylesReset(start int32, length int32, ranges []int32, styles []*StyleRange, reset bool) {
	var charCount int32 = this.content.GetCharCount()
	if reset {
		start = 0
		length = charCount
	}
	var formerRanges []int32 = this.GetRangesStartLength(start, length)
	var formerStyles []*StyleRange = this.GetStyleRangesStartLength(start, length)
	var end int32 = start + length
	var wasFixedLineHeight bool = this.IsFixedLineHeight()
	if start > end || start < 0 {
		Error(ERROR_INVALID_RANGE)
	}
	if styles != (nil) {
		if end > charCount {
			Error(ERROR_INVALID_RANGE)
		}
		if ranges != (nil) {
			if int32(len(ranges)) != int32(len(styles))<<1 {
				Error(ERROR_INVALID_ARGUMENT)
			}
		}
		var lastOffset int32 = 0
		for i := int32(0); i < int32(len(styles)); i++ {
			if styles[i] == (nil) {
				Error(ERROR_INVALID_ARGUMENT)
			}
			var rangeStart int32
			var rangeLength int32
			if ranges != (nil) {
				rangeStart = ranges[i<<1]
				rangeLength = ranges[(i<<1)+1]
			} else {
				rangeStart = styles[i].Start
				rangeLength = styles[i].Length
			}
			if rangeLength < 0 {
				Error(ERROR_INVALID_ARGUMENT)
			}
			if !(0 <= rangeStart && rangeStart+rangeLength <= charCount) {
				Error(ERROR_INVALID_ARGUMENT)
			}
			if lastOffset > rangeStart {
				Error(ERROR_INVALID_ARGUMENT)
			}
			b876 := styles[i].IsVariableHeight()
			this.hasStyleWithVariableHeight = this.hasStyleWithVariableHeight || b876
			lastOffset = rangeStart + rangeLength
		}
	}
	var rangeStart int32 = start
	var rangeEnd int32 = end
	if styles != (nil) && int32(len(styles)) > 0 {
		if ranges != (nil) {
			rangeStart = ranges[0]
			rangeEnd = ranges[int32(len(ranges))-2] + ranges[int32(len(ranges))-1]
		} else {
			rangeStart = styles[0].Start
			rangeEnd = styles[int32(len(styles))-1].Start + styles[int32(len(styles))-1].Length
		}
	}
	var expectedBottom int32 = 0
	if !this.IsFixedLineHeight() && !reset {
		var lineEnd int32 = this.content.GetLineAtOffset(int32(math.Max(float64(end), float64(rangeEnd))))
		var partialTopIndex int32 = this.GetPartialTopIndex()
		var partialBottomIndex int32 = this.GetPartialBottomIndex()
		if partialTopIndex <= lineEnd && lineEnd <= partialBottomIndex {
			expectedBottom = this.GetLinePixel(lineEnd + 1)
		}
	}
	if reset {
		this.renderer.SetStyleRanges(nil, nil)
	} else {
		this.renderer.UpdateRanges(start, length, length)
	}
	if styles != (nil) && int32(len(styles)) > 0 {
		this.renderer.SetStyleRanges(ranges, styles)
	}
	this.hasStyleWithVariableHeight = false
	for _, style := range this.GetStyleRangesIncludeRanges(false) {
		this.hasStyleWithVariableHeight = style.IsVariableHeight()
		if this.hasStyleWithVariableHeight {
			break
		}
	}
	var modifiedLines *jrt.TreeSet = this.ComputeModifiedLines(formerRanges, formerStyles, ranges, styles)
	this.ResetCache(modifiedLines)
	if reset {
		this.Canvas.redraw_()
	} else {
		var lineStart int32 = this.content.GetLineAtOffset(int32(math.Min(float64(start), float64(rangeStart))))
		var lineEnd int32 = this.content.GetLineAtOffset(int32(math.Max(float64(end), float64(rangeEnd))))
		var partialTopIndex int32 = this.GetPartialTopIndex()
		var partialBottomIndex int32 = this.GetPartialBottomIndex()
		if !(lineStart > partialBottomIndex || lineEnd < partialTopIndex) {
			var top int32 = 0
			var bottom int32 = this.clientAreaHeight
			if partialTopIndex <= lineStart && lineStart <= partialBottomIndex {
				top = int32(math.Max(float64(0), float64(this.GetLinePixel(lineStart))))
			}
			if partialTopIndex <= lineEnd && lineEnd <= partialBottomIndex {
				bottom = this.GetLinePixel(lineEnd + 1)
			}
			if !(wasFixedLineHeight && this.IsFixedLineHeight()) && bottom != expectedBottom {
				bottom = this.clientAreaHeight
			}
			this.Canvas.redrawXYWidthHeightAll_(0, top, this.clientAreaWidth, bottom-top, false)
		}
	}
	var oldColumnX int32 = this.columnX
	this.SetCaretLocations()
	this.columnX = oldColumnX
	this.DoMouseLinkCursor()
}

func (this *StyledText) ComputeModifiedLines(referenceRanges []int32, referenceStyles []*StyleRange, newRanges []int32, newStyles []*StyleRange) *jrt.TreeSet {
	if referenceStyles == (nil) {
		referenceStyles = make([]*StyleRange, 0)
	}
	if referenceRanges == (nil) {
		referenceRanges = this.CreateRanges(referenceStyles)
	}
	if newStyles == (nil) {
		newStyles = make([]*StyleRange, 0)
	}
	if newRanges == (nil) {
		newRanges = this.CreateRanges(newStyles)
	}
	if int32(len(referenceRanges)) != 2*int32(len(referenceStyles)) {
		panic(jrt.NewIllegalArgumentException())
	}
	if int32(len(newRanges)) != 2*int32(len(newStyles)) {
		panic(jrt.NewIllegalArgumentException())
	}
	var res *jrt.TreeSet = jrt.NewTreeSet()
	var referenceRangeIndex int32 = 0
	var newRangeIndex int32 = 0
	var defaultStyle *StyleRange = NewStyleRange()
	defaultStyle.Foreground = this.foreground
	defaultStyle.Background = this.background
	defaultStyle.Font = this.GetFont()
	var currentOffset int32
	if int32(len(referenceRanges)) > 0 {
		currentOffset = referenceRanges[0]
	} else {
		currentOffset = math.MaxInt32
	}
	if int32(len(newRanges)) > 0 {
		currentOffset = int32(math.Min(float64(currentOffset), float64(newRanges[0])))
	}
	for currentOffset < this.content.GetCharCount() && (referenceRangeIndex < int32(len(referenceStyles)) || newRangeIndex < int32(len(newRanges))) {
		var nextMilestoneOffset int32 = math.MaxInt32
		for referenceRangeIndex < int32(len(referenceStyles)) && this.EndRangeOffset(referenceRanges, referenceRangeIndex) <= currentOffset {
			referenceRangeIndex++
		}
		var referenceStyleAtCurrentOffset *StyleRange = defaultStyle
		if this.IsInRange(referenceRanges, referenceRangeIndex, currentOffset) {
			referenceStyleAtCurrentOffset = referenceStyles[referenceRangeIndex]
			nextMilestoneOffset = this.EndRangeOffset(referenceRanges, referenceRangeIndex)
		} else {
			if referenceRangeIndex < int32(len(referenceStyles)) {
				nextMilestoneOffset = referenceRanges[2*referenceRangeIndex]
			}
		}
		for newRangeIndex < int32(len(newStyles)) && this.EndRangeOffset(newRanges, newRangeIndex) <= currentOffset {
			newRangeIndex++
		}
		var newStyleAtCurrentOffset *StyleRange = defaultStyle
		if this.IsInRange(newRanges, newRangeIndex, currentOffset) {
			newStyleAtCurrentOffset = newStyles[newRangeIndex]
			nextMilestoneOffset = int32(math.Min(float64(nextMilestoneOffset), float64(this.EndRangeOffset(newRanges, newRangeIndex))))
		} else {
			if newRangeIndex < int32(len(newStyles)) {
				nextMilestoneOffset = int32(math.Min(float64(nextMilestoneOffset), float64(newRanges[2*newRangeIndex])))
			}
		}
		if !referenceStyleAtCurrentOffset.SimilarTo(newStyleAtCurrentOffset) {
			var fromLine int32 = this.GetLineAtOffset(currentOffset)
			var toLine int32 = this.GetLineAtOffset(nextMilestoneOffset - 1)
			for line := int32(fromLine); line <= toLine; line++ {
				res.Add(int32(line))
			}
			if toLine+1 < this.GetLineCount() {
				currentOffset = this.GetOffsetAtLine(toLine + 1)
			} else {
				currentOffset = this.content.GetCharCount()
			}
		} else {
			currentOffset = nextMilestoneOffset
		}
	}
	return res
}

func (this *StyledText) CreateRanges(referenceStyles []*StyleRange) []int32 {
	var referenceRanges []int32
	referenceRanges = make([]int32, 2*int32(len(referenceStyles)))
	for i := int32(0); i < int32(len(referenceStyles)); i++ {
		referenceRanges[2*i] = referenceStyles[i].Start
		referenceRanges[2*i+1] = referenceStyles[i].Length
	}
	return referenceRanges
}

func (this *StyledText) IsInRange(ranges []int32, styleIndex int32, offset int32) bool {
	if ranges == (nil) || int32(len(ranges)) == 0 || styleIndex < 0 || 2*styleIndex+1 > int32(len(ranges)) {
		return false
	}
	var start int32 = ranges[2*styleIndex]
	var length int32 = ranges[2*styleIndex+1]
	return offset >= start && offset < start+length
}

func (this *StyledText) EndRangeOffset(ranges []int32, styleIndex int32) int32 {
	if styleIndex < 0 || 2*styleIndex > int32(len(ranges)) {
		panic(jrt.NewIllegalArgumentException())
	}
	var start int32 = ranges[2*styleIndex]
	var length int32 = ranges[2*styleIndex+1]
	return start + length
}

