func (this *StyledText) SetTopIndex(topIndex int32) {
	this.CheckWidget()
	if this.GetCharCount() == 0 {
		return
	}
	var lineCount int32 = this.content.GetLineCount()
	var pixel int32
	if this.IsFixedLineHeight() {
		var pageSize int32 = int32(math.Max(float64(1), float64(int32(math.Min(float64(lineCount), float64(this.GetLineCountWhole()))))))
		if topIndex < 0 {
			topIndex = 0
		} else {
			if topIndex > lineCount-pageSize {
				topIndex = lineCount - pageSize
			}
		}
		pixel = this.GetLinePixel(topIndex)
	} else {
		topIndex = int32(math.Max(float64(0), float64(int32(math.Min(float64(lineCount-1), float64(topIndex))))))
		pixel = this.GetLinePixel(topIndex)
		if pixel > 0 {
			pixel = this.GetAvailableHeightBellow(pixel)
		} else {
			pixel = this.GetAvailableHeightAbove(pixel)
		}
	}
	this.ScrollVertical(pixel, true)
}

