func (this *StyledText) SetTopPixel(pixel int32) {
	this.CheckWidget()
	if this.GetCharCount() == 0 {
		return
	}
	if pixel < 0 {
		pixel = 0
	}
	var lineCount int32 = this.content.GetLineCount()
	var height int32 = this.clientAreaHeight - this.topMargin - this.bottomMargin
	var verticalOffset int32 = this.GetVerticalScrollOffset()
	if this.IsFixedLineHeight() {
		var maxTopPixel int32 = int32(math.Max(float64(0), float64(lineCount*this.GetVerticalIncrement()-height)))
		if pixel > maxTopPixel {
			pixel = maxTopPixel
		}
		pixel -= verticalOffset
	} else {
		pixel -= verticalOffset
		if pixel > 0 {
			pixel = this.GetAvailableHeightBellow(pixel)
		}
	}
	this.ScrollVertical(pixel, true)
}

