func (this *StyledText) ShowLocation(rectLike RectangleLike, scrollPage bool) bool {
	var rect *Rectangle
	if rectLike != nil {
		rect = rectLike.AsRectangle()
	}
	_ = rect
	var scrolled bool = false
	if rect.Y < this.topMargin {
		scrolled = this.ScrollVertical(rect.Y-this.topMargin, true)
	} else {
		if rect.Y+rect.Height > this.clientAreaHeight-this.bottomMargin {
			if this.clientAreaHeight-this.topMargin-this.bottomMargin <= 0 {
				scrolled = this.ScrollVertical(rect.Y-this.topMargin, true)
			} else {
				scrolled = this.ScrollVertical(rect.Y+rect.Height-(this.clientAreaHeight-this.bottomMargin), true)
			}
		}
	}
	var width int32 = this.clientAreaWidth - this.rightMargin - this.leftMargin
	if width > 0 {
		var minScroll int32
		if scrollPage {
			minScroll = width / 4
		} else {
			minScroll = 0
		}
		if rect.X < this.leftMargin {
			var scrollWidth int32 = int32(math.Max(float64(this.leftMargin-rect.X), float64(minScroll)))
			var maxScroll int32 = this.horizontalScrollOffset
			scrolled = this.ScrollHorizontal(-int32(math.Min(float64(maxScroll), float64(scrollWidth))), true)
		} else {
			if rect.X+rect.Width > (this.clientAreaWidth - this.rightMargin) {
				var scrollWidth int32 = int32(math.Max(float64(rect.X+rect.Width-(this.clientAreaWidth-this.rightMargin)), float64(minScroll)))
				var maxScroll int32 = this.renderer.GetWidth() - this.horizontalScrollOffset - this.clientAreaWidth
				scrolled = this.ScrollHorizontal(int32(math.Min(float64(maxScroll), float64(scrollWidth))), true)
			}
		}
	}
	return scrolled
}

func (this *StyledText) ShowCaret() {
	var bounds *Rectangle = this.GetBoundsAtOffset(this.caretOffsets[0])
	if !this.ShowLocation(bounds, true) || (this.carets != (nil) && int32(len(this.caretOffsets)) != int32(len(this.carets))) {
		this.SetCaretLocations()
	}
}

func (this *StyledText) ShowSelection() {
	this.CheckWidget()
	var rightToLeft bool = this.caretOffsets[0] == this.selection[0].X
	var startOffset int32
	var endOffset int32
	if rightToLeft {
		startOffset = this.selection[0].Y
		endOffset = this.selection[0].X
	} else {
		startOffset = this.selection[0].X
		endOffset = this.selection[0].Y
	}
	var startBounds *Rectangle = this.GetBoundsAtOffset(startOffset)
	var endBounds *Rectangle = this.GetBoundsAtOffset(endOffset)
	var w int32 = this.clientAreaWidth - this.leftMargin - this.rightMargin
	var selectionFits bool
	if rightToLeft {
		selectionFits = startBounds.X-endBounds.X <= w
	} else {
		selectionFits = endBounds.X-startBounds.X <= w
	}
	if selectionFits {
		if this.ShowLocation(startBounds, false) {
			endBounds = this.GetBoundsAtOffset(endOffset)
		}
		if endOffset == this.caretOffsets[0] {
			endBounds.Width = this.GetCaretWidth()
		} else {
			endBounds.Width = 0
		}
		this.ShowLocation(endBounds, false)
	} else {
		this.ShowLocation(endBounds, true)
	}
}

func (this *StyledText) UpdateCaretVisibility() {
	var caret *Caret = this.GetCaret()
	if caret != (nil) {
		if this.carets == (nil) || int32(len(this.carets)) == 0 {
			this.carets = []*Caret{caret}
		}
		if this.blockSelection && this.blockXLocation != -1 {
			jrt.ArraysAsList(this.carets).ForEach(func(c *Caret) {
				c.SetVisible(false)
			})
		} else {
			jrt.ArraysAsList(this.carets).ForEach(func(c *Caret) {
				var location *Point = c.GetLocation()
				var size *Point = c.GetSize()
				var visible bool = this.topMargin <= location.Y+size.Y && location.Y <= this.clientAreaHeight-this.bottomMargin && this.leftMargin <= location.X+size.X && location.X <= this.clientAreaWidth-this.rightMargin
				c.SetVisible(visible)
			})
		}
	}
}

func (this *StyledText) UpdateSelection(startOffset int32, replacedLength int32, newLength int32) {
	if this.selection[int32(len(this.selection))-1].Y <= startOffset {
		if this.IsWordWrap() {
			this.SetCaretLocations()
		}
		return
	}
	jrt.ArraysAsList(this.selection).Filter(func(sel *Point) bool {
		return sel.Y > startOffset
	}).Filter(func(sel *Point) bool {
		return sel.X < startOffset
	}).ForEach(func(sel *Point) {
		this.InternalRedrawRange(sel.X, startOffset-sel.X)
	})
	jrt.ArraysAsList(this.selection).Filter(func(sel *Point) bool {
		return sel.Y > startOffset
	}).Filter(func(sel *Point) bool {
		return sel.Y > startOffset+replacedLength && sel.X < startOffset+replacedLength
	}).ForEach(func(sel *Point) {
		var netNewLength int32 = newLength - replacedLength
		var redrawStart int32 = startOffset + newLength
		this.InternalRedrawRange(redrawStart, sel.Y+netNewLength-redrawStart)
	})
	this.SetSelectionRegionsSendEventDoBlock(jrt.ToSlice[int32](jrt.ArraysAsList(this.selection).Map(func(sel *Point) *Point {
		if sel.Y <= startOffset {
			return sel
		} else {
			if sel.X == startOffset && sel.Y == startOffset+replacedLength {
				return NewPoint(startOffset+newLength, startOffset+newLength)
			} else {
				if sel.Y > startOffset && sel.X < startOffset+replacedLength {
					return NewPoint(startOffset+newLength, startOffset+newLength)
				} else {
					var x int32 = sel.X + newLength - replacedLength
					var y int32 = sel.X + newLength - replacedLength + (sel.Y - sel.X)
					var cond877 int32
					if x < 0 {
						cond877 = 0
					} else {
						cond877 = x
					}
					var cond878 int32
					if y < 0 {
						cond878 = 0
					} else {
						cond878 = y
					}
					return NewPoint(cond877, cond878)
				}
			}
		}
	}).FlatMapToInt(func(p *Point) *jrt.List {
		return jrt.IntStreamOf(p.X, p.Y-p.X)
	})), true, false)
	this.SetCaretLocations()
}

func (this *StyledText) HandleDPIChange(event *Event) {
	this.UpdateCaretVisibility()
	this.SetCaretLocations()
	var caretSet *jrt.List = jrt.NewList()
	caretSet.Add(this.defaultCaret)
	caretSet.Add(this.GetCaret())
	if this.carets != (nil) {
		for _, caret := range this.carets {
			caretSet.Add(caret)
		}
	}
	for _, elem879 := range caretSet.ToArray() {
		caretToRefresh := jrt.Cast[*Caret](elem879)
		if caretToRefresh != (nil) && !caretToRefresh.IsDisposed() {
			caretToRefresh.NotifyListeners(ZoomChanged, event)
		}
	}
}

