func StyledTextCheckStyle(style int32) int32 {
	if (style & SINGLE) != 0 {
		style &= ^(H_SCROLL | V_SCROLL | WRAP | MULTI)
	} else {
		style |= MULTI
		if (style & WRAP) != 0 {
			style &= ^H_SCROLL
		}
	}
	style |= NO_REDRAW_RESIZE | DOUBLE_BUFFERED | NO_BACKGROUND
	return style & ^CENTER
}

type StyledText_Printing struct {
	printer         *Printer
	printerRenderer *StyledTextRenderer
	printOptions    *StyledTextPrintOptions
	clientArea      *Rectangle
	fontData        *FontData
	printerFont     *Font
	resources       *jrt.Map
	tabLength       int32
	gc              *GC
	pageWidth       int32
	startPage       int32
	endPage         int32
	scope           int32
	startLine       int32
	endLine         int32
	singleLine      bool
	selection       []*Point
	mirrored        bool
	lineSpacing     int32
	printMargin     int32
}

func init() { jrt.RegisterClassPackage("StyledText_Printing", "org.eclipse.swt.custom") }

func (this *StyledText_Printing) AsStyledText_Printing() *StyledText_Printing { return this }

type StyledText_PrintingLike interface {
	AsStyledText_Printing() *StyledText_Printing
}

const StyledTextPrintingLEFT int32 = 0

const StyledTextPrintingCENTER int32 = 1

const StyledTextPrintingRIGHT int32 = 2

func newStyledTextPrinting(styledText *StyledText, printer *Printer, printOptions *StyledTextPrintOptions) *StyledText_Printing {
	this := &StyledText_Printing{}
	this.initStyledTextPrinting(styledText, printer, printOptions)
	return this
}

func (this *StyledText_Printing) initStyledTextPrinting(styledText *StyledText, printer *Printer, printOptions *StyledTextPrintOptions) {
	this.selection = []*Point{NewPoint(0, 0)}
	this.printer = printer
	this.printOptions = printOptions
	this.mirrored = (styledText.impl.getStyle_() & MIRRORED) != 0
	this.singleLine = styledText.IsSingleLine()
	this.startPage = 1
	this.endPage = math.MaxInt32
	var data *PrinterData = printer.GetPrinterData()
	this.scope = data.Scope
	if this.scope == PrinterDataPAGE_RANGE {
		this.startPage = data.StartPage
		this.endPage = data.EndPage
		if this.endPage < this.startPage {
			var temp int32 = this.endPage
			this.endPage = this.startPage
			this.startPage = temp
		}
	} else {
		if this.scope == PrinterDataSELECTION {
			this.selection = jrt.CopyOf(styledText.selection, int32(len(styledText.selection)))
		}
	}
	this.printerRenderer = newStyledTextRenderer(upcastPrinterToDevice(printer), nil)
	this.printerRenderer.SetContent(this.CopyContent(styledText.GetContent()))
	this.CacheLineData(styledText)
}

func (this *StyledText_Printing) CacheLineData(styledTextLike StyledTextLike) {
	var styledText *StyledText
	if styledTextLike != nil {
		styledText = styledTextLike.AsStyledText()
	}
	_ = styledText
	var renderer *StyledTextRenderer = styledText.renderer
	renderer.CopyInto(this.printerRenderer)
	this.fontData = styledText.GetFont().GetFontData()[0]
	this.tabLength = styledText.tabLength
	var lineCount int32 = this.printerRenderer.lineCount
	if styledText.IsListening(STLineGetBackground) || (styledText.IsListening(STLineGetSegments)) || styledText.IsListening(STLineGetStyle) {
		var content StyledTextContent = this.printerRenderer.content
		for i := int32(0); i < lineCount; i++ {
			var line string = content.GetLine(i)
			var lineOffset int32 = content.GetOffsetAtLine(i)
			var event *StyledTextEvent = styledText.GetLineBackgroundData(lineOffset, line)
			if event != (nil) && event.lineBackground != (nil) {
				this.printerRenderer.SetLineBackground(i, 1, event.lineBackground)
			}
			event = styledText.GetBidiSegments(lineOffset, line)
			if event != (nil) {
				this.printerRenderer.SetLineSegments(i, 1, event.Segments)
				this.printerRenderer.SetLineSegmentChars(i, 1, event.SegmentsChars)
			}
			event = styledText.GetLineStyleData(lineOffset, line)
			if event != (nil) {
				this.printerRenderer.SetLineIndent(i, 1, event.indent)
				this.printerRenderer.SetLineAlignment(i, 1, event.alignment)
				this.printerRenderer.SetLineJustify(i, 1, event.justify)
				this.printerRenderer.SetLineBullet(i, 1, event.bullet)
				var styles []*StyleRange = event.styles
				if styles != (nil) && int32(len(styles)) > 0 {
					this.printerRenderer.SetStyleRanges(event.ranges, styles)
				}
			}
		}
	}
	var printerDPI *Point = this.printer.impl.getDPI_()
	this.resources = jrt.NewMap()
	var scaleFactorX int32 = printerDPI.X / 100
	var scaleFactorY int32 = printerDPI.Y / 100
	for i := int32(0); i < lineCount; i++ {
		var color *Color = this.printerRenderer.GetLineBackground(i, nil)
		if color != (nil) {
			if this.printOptions.PrintLineBackground {
				var printerColor *Color = castResourceToColor(jrt.Cast[*Resource](this.resources.Get(color)))
				if printerColor == (nil) {
					printerColor = NewColorRgb(color.GetRGB())
					jrt.Cast[*Resource](this.resources.Put(upcastColorToResource(color), upcastColorToResource(printerColor)))
				}
				this.printerRenderer.SetLineBackground(i, 1, printerColor)
			} else {
				this.printerRenderer.SetLineBackground(i, 1, nil)
			}
		}
		var indent int32 = this.printerRenderer.GetLineIndent(i, 0)
		if indent != 0 {
			this.printerRenderer.SetLineIndent(i, 1, indent*scaleFactorX)
		}
	}
	var styles []*StyleRange = this.printerRenderer.styles
	for i := int32(0); i < this.printerRenderer.styleCount; i++ {
		var style *StyleRange = styles[i]
		var font *Font = style.Font
		if style.Font != (nil) {
			var printerFont *Font = castResourceToFont(jrt.Cast[*Resource](this.resources.Get(font)))
			if printerFont == (nil) {
				printerFont = NewFontDeviceFds(upcastPrinterToDevice(this.printer), font.GetFontData())
				jrt.Cast[*Resource](this.resources.Put(upcastFontToResource(font), upcastFontToResource(printerFont)))
			}
			style.Font = printerFont
		}
		var color *Color = style.Foreground
		if color != (nil) {
			var printerColor *Color = castResourceToColor(jrt.Cast[*Resource](this.resources.Get(color)))
			if this.printOptions.PrintTextForeground {
				if printerColor == (nil) {
					printerColor = NewColorRgb(color.GetRGB())
					jrt.Cast[*Resource](this.resources.Put(upcastColorToResource(color), upcastColorToResource(printerColor)))
				}
				style.Foreground = printerColor
			} else {
				style.Foreground = nil
			}
		}
		color = style.Background
		if color != (nil) {
			var printerColor *Color = castResourceToColor(jrt.Cast[*Resource](this.resources.Get(color)))
			if this.printOptions.PrintTextBackground {
				if printerColor == (nil) {
					printerColor = NewColorRgb(color.GetRGB())
					jrt.Cast[*Resource](this.resources.Put(upcastColorToResource(color), upcastColorToResource(printerColor)))
				}
				style.Background = printerColor
			} else {
				style.Background = nil
			}
		}
		if !this.printOptions.PrintTextFontStyle {
			style.FontStyle = NORMAL
		}
		style.Rise = style.Rise * scaleFactorY
		var metrics *GlyphMetrics = style.Metrics
		if metrics != (nil) {
			metrics.Ascent = metrics.Ascent * scaleFactorY
			metrics.Descent = metrics.Descent * scaleFactorY
			metrics.Width = metrics.Width * scaleFactorX
		}
	}
	this.lineSpacing = styledText.lineSpacing * scaleFactorY
	if this.printOptions.PrintLineNumbers {
		this.printMargin = 3 * scaleFactorX
	}
}

func (this *StyledText_Printing) CopyContent(original StyledTextContent) StyledTextContent {
	var printerContent StyledTextContent = newDefaultContent()
	var insertOffset int32 = 0
	for i := int32(0); i < original.GetLineCount(); i++ {
		var insertEndOffset int32
		if i < original.GetLineCount()-1 {
			insertEndOffset = original.GetOffsetAtLine(i + 1)
		} else {
			insertEndOffset = original.GetCharCount()
		}
		printerContent.ReplaceTextRange(insertOffset, 0, original.GetTextRange(insertOffset, insertEndOffset-insertOffset))
		insertOffset = insertEndOffset
	}
	return printerContent
}

func (this *StyledText_Printing) Dispose() {
	if this.gc != (nil) {
		this.gc.impl.dispose_()
		this.gc = nil
	}
	if this.resources != (nil) {
		for _, elem880 := range this.resources.Values().ToArray() {
			resource := jrt.Cast[*Resource](elem880)
			resource.impl.dispose_()
		}
		this.resources = nil
	}
	if this.printerFont != (nil) {
		this.printerFont.impl.dispose_()
		this.printerFont = nil
	}
	if this.printerRenderer != (nil) {
		this.printerRenderer.Dispose()
		this.printerRenderer = nil
	}
}

func (this *StyledText_Printing) Init() {
	var trim *Rectangle = this.printer.ComputeTrim(0, 0, 0, 0)
	var dpi *Point = this.printer.impl.getDPI_()
	this.printerFont = NewFontDeviceNameHeightStyle(upcastPrinterToDevice(this.printer), this.fontData.GetName(), this.fontData.GetHeight(), NORMAL)
	this.clientArea = this.printer.impl.getClientArea_()
	this.pageWidth = this.clientArea.Width
	this.clientArea.X = dpi.X + trim.X
	this.clientArea.Y = dpi.Y + trim.Y
	this.clientArea.Width -= (this.clientArea.X + trim.Width)
	this.clientArea.Height -= (this.clientArea.Y + trim.Height)
	var style int32
	if this.mirrored {
		style = RIGHT_TO_LEFT
	} else {
		style = LEFT_TO_RIGHT
	}
	this.gc = NewGCDrawableStyle(this.printer, style)
	this.gc.SetFont(this.printerFont)
	this.printerRenderer.SetFont(this.printerFont, this.tabLength)
	var lineHeight int32 = this.printerRenderer.GetLineHeight()
	if this.printOptions.Header != "" {
		this.clientArea.Y += lineHeight * 2
		this.clientArea.Height -= lineHeight * 2
	}
	if this.printOptions.Footer != "" {
		this.clientArea.Height -= lineHeight * 2
	}
	var content StyledTextContent = this.printerRenderer.content
	this.startLine = 0
	if this.singleLine {
		this.endLine = 0
	} else {
		this.endLine = content.GetLineCount() - 1
	}
	if this.scope == PrinterDataPAGE_RANGE {
		var pageSize int32 = this.clientArea.Height / lineHeight
		this.startLine = (this.startPage - 1) * pageSize
	} else {
		if this.scope == PrinterDataSELECTION {
			this.startLine = content.GetLineAtOffset(this.selection[0].X)
			if this.selection[0].Y > 0 {
				this.endLine = content.GetLineAtOffset(this.selection[0].Y)
			} else {
				this.endLine = this.startLine - 1
			}
		}
	}
}

func (this *StyledText_Printing) Print() {
	var background *Color = this.gc.GetBackground()
	var foreground *Color = this.gc.GetForeground()
	var paintY int32 = this.clientArea.Y
	var paintX int32 = this.clientArea.X
	var width int32 = this.clientArea.Width
	var page int32 = this.startPage
	var pageBottom int32 = this.clientArea.Y + this.clientArea.Height
	var orientation int32 = this.gc.GetStyle() & (RIGHT_TO_LEFT | LEFT_TO_RIGHT)
	var printLayout *TextLayout = nil
	if this.printOptions.PrintLineNumbers || this.printOptions.Header != "" || this.printOptions.Footer != "" {
		printLayout = NewTextLayout(upcastPrinterToDevice(this.printer))
		printLayout.SetFont(this.printerFont)
	}
	if this.printOptions.PrintLineNumbers {
		var numberingWidth int32 = 0
		var count int32 = this.endLine - this.startLine + 1
		var lineLabels []string = this.printOptions.LineLabels
		if lineLabels != (nil) {
			for i := int32(this.startLine); i < int32(math.Min(float64(count), float64(int32(len(lineLabels))))); i++ {
				if lineLabels[i] != "" {
					printLayout.SetText(lineLabels[i])
					var lineWidth int32 = printLayout.GetBounds().Width
					numberingWidth = int32(math.Max(float64(numberingWidth), float64(lineWidth)))
				}
			}
		} else {
			var buffer *jrt.StringBuilder = jrt.NewStringBuilder("0")
			for {
				count /= 10
				if !((count) > 0) {
					break
				}
				buffer.Append("0")
			}
			printLayout.SetText(buffer.ToString())
			numberingWidth = printLayout.GetBounds().Width
		}
		numberingWidth += this.printMargin
		if numberingWidth > width {
			numberingWidth = width
		}
		paintX += numberingWidth
		width -= numberingWidth
	}
	for i := int32(this.startLine); i <= this.endLine && page <= this.endPage; i++ {
		if paintY == this.clientArea.Y {
			this.printer.StartPage()
			this.PrintDecoration(page, true, printLayout)
		}
		var layout *TextLayout = this.printerRenderer.GetTextLayoutLineIndexOrientationWidthLineSpacing(i, orientation, width, this.lineSpacing)
		var lineBackground *Color = this.printerRenderer.GetLineBackground(i, background)
		var paragraphBottom int32 = paintY + layout.GetBounds().Height
		if paragraphBottom <= pageBottom {
			this.PrintLine(paintX, paintY, this.gc, foreground, lineBackground, layout, printLayout, i)
			paintY = paragraphBottom
		} else {
			var lineCount int32 = layout.GetLineCount()
			for paragraphBottom > pageBottom && lineCount > 0 {
				lineCount--
				paragraphBottom -= layout.GetLineBounds(lineCount).Height + layout.GetSpacing()
			}
			if lineCount == 0 {
				this.PrintDecoration(page, false, printLayout)
				this.printer.EndPage()
				page++
				if page <= this.endPage {
					this.printer.StartPage()
					this.PrintDecoration(page, true, printLayout)
					paintY = this.clientArea.Y
					this.PrintLine(paintX, paintY, this.gc, foreground, lineBackground, layout, printLayout, i)
					paintY += layout.GetBounds().Height
				}
			} else {
				var height int32 = paragraphBottom - paintY
				this.gc.SetClipping(this.clientArea.X, paintY, this.clientArea.Width, height)
				this.PrintLine(paintX, paintY, this.gc, foreground, lineBackground, layout, printLayout, i)
				this.gc.SetClippingOverload2(nil)
				this.PrintDecoration(page, false, printLayout)
				this.printer.EndPage()
				page++
				if page <= this.endPage {
					this.printer.StartPage()
					this.PrintDecoration(page, true, printLayout)
					paintY = this.clientArea.Y - height
					var layoutHeight int32 = layout.GetBounds().Height
					this.gc.SetClipping(this.clientArea.X, this.clientArea.Y, this.clientArea.Width, layoutHeight-height)
					this.PrintLine(paintX, paintY, this.gc, foreground, lineBackground, layout, printLayout, i)
					this.gc.SetClippingOverload2(nil)
					paintY += layoutHeight
				}
			}
		}
		this.printerRenderer.DisposeTextLayout(layout)
	}
	if page <= this.endPage && paintY > this.clientArea.Y {
		this.PrintDecoration(page, false, printLayout)
		this.printer.EndPage()
	}
	if printLayout != (nil) {
		printLayout.impl.dispose_()
	}
}

func (this *StyledText_Printing) PrintDecoration(page int32, header bool, layoutLike TextLayoutLike) {
	var layout *TextLayout
	if layoutLike != nil {
		layout = layoutLike.AsTextLayout()
	}
	_ = layout
	var text string
	if header {
		text = this.printOptions.Header
	} else {
		text = this.printOptions.Footer
	}
	if text == "" {
		return
	}
	var lastSegmentIndex int32 = 0
	for i := int32(0); i < 3; i++ {
		var segmentIndex int32 = jrt.IndexFrom(text, StyledTextPrintOptionsSEPARATOR, lastSegmentIndex)
		var segment string
		if segmentIndex == -1 {
			segment = jrt.Substring(text, lastSegmentIndex, -1)
			this.PrintDecorationSegment(segment, i, page, header, layout)
			break
		} else {
			segment = jrt.Substring(text, lastSegmentIndex, segmentIndex)
			this.PrintDecorationSegment(segment, i, page, header, layout)
			lastSegmentIndex = segmentIndex + jrt.StringLength(StyledTextPrintOptionsSEPARATOR)
		}
	}
}

func (this *StyledText_Printing) PrintDecorationSegment(segment string, alignment int32, page int32, header bool, layoutLike TextLayoutLike) {
	var layout *TextLayout
	if layoutLike != nil {
		layout = layoutLike.AsTextLayout()
	}
	_ = layout
	var pageIndex int32 = jrt.IndexFrom(segment, StyledTextPrintOptionsPAGE_TAG, 0)
	if pageIndex != -1 {
		var pageTagLength int32 = jrt.StringLength(StyledTextPrintOptionsPAGE_TAG)
		var buffer *jrt.StringBuilder = jrt.NewStringBuilder(jrt.Substring(segment, 0, pageIndex))
		buffer.Append(page)
		buffer.Append(jrt.Substring(segment, pageIndex+pageTagLength, -1))
		segment = buffer.ToString()
	}
	if jrt.StringLength(segment) > 0 {
		layout.SetText(segment)
		var segmentWidth int32 = layout.GetBounds().Width
		var segmentHeight int32 = this.printerRenderer.GetLineHeight()
		var drawX int32 = 0
		var drawY int32
		if alignment == StyledTextPrintingLEFT {
			drawX = this.clientArea.X
		} else {
			if alignment == StyledTextPrintingCENTER {
				drawX = (this.pageWidth - segmentWidth) / 2
			} else {
				if alignment == StyledTextPrintingRIGHT {
					drawX = this.clientArea.X + this.clientArea.Width - segmentWidth
				}
			}
		}
		if header {
			drawY = this.clientArea.Y - segmentHeight*2
		} else {
			drawY = this.clientArea.Y + this.clientArea.Height + segmentHeight
		}
		layout.Draw(this.gc, drawX, drawY)
	}
}

func (this *StyledText_Printing) PrintLine(x int32, y int32, gcLike GCLike, foregroundLike ColorLike, backgroundLike ColorLike, layoutLike TextLayoutLike, printLayoutLike TextLayoutLike, index int32) {
	var gc *GC
	if gcLike != nil {
		gc = gcLike.AsGC()
	}
	_ = gc
	var foreground *Color
	if foregroundLike != nil {
		foreground = foregroundLike.AsColor()
	}
	_ = foreground
	var background *Color
	if backgroundLike != nil {
		background = backgroundLike.AsColor()
	}
	_ = background
	var layout *TextLayout
	if layoutLike != nil {
		layout = layoutLike.AsTextLayout()
	}
	_ = layout
	var printLayout *TextLayout
	if printLayoutLike != nil {
		printLayout = printLayoutLike.AsTextLayout()
	}
	_ = printLayout
	if background != (nil) {
		var rect *Rectangle = layout.GetBounds()
		gc.SetBackground(background)
		gc.FillRectangle(x, y, rect.Width, rect.Height)
	}
	if this.printOptions.PrintLineNumbers {
		var metrics *FontMetrics = layout.GetLineMetrics(0)
		printLayout.SetAscent(metrics.GetAscent() + metrics.GetLeading())
		printLayout.SetDescent(metrics.GetDescent())
		var lineLabels []string = this.printOptions.LineLabels
		if lineLabels != (nil) {
			if 0 <= index && index < int32(len(lineLabels)) && lineLabels[index] != "" {
				printLayout.SetText(lineLabels[index])
			} else {
				printLayout.SetText("")
			}
		} else {
			printLayout.SetText(fmt.Sprint(index))
		}
		var paintX int32 = x - this.printMargin - printLayout.GetBounds().Width
		printLayout.Draw(gc, paintX, y)
		printLayout.SetAscent(-1)
		printLayout.SetDescent(-1)
	}
	gc.SetForeground(foreground)
	layout.Draw(gc, x, y)
}

func (this *StyledText_Printing) Run() {
	var jobName string = this.printOptions.JobName
	if jobName == "" {
		jobName = "Printing"
	}
	if this.printer.StartJob(jobName) {
		this.Init()
		this.Print()
		this.Dispose()
		this.printer.EndJob()
	}
}

